const items = $input.all();

const projects = [];
const warnings = [];
const usedIds = new Set();

for (const item of items) {

  const profile = item.json.data ?? item.json;

  // Ignorar plantillas y proyectos inactivos
  if (profile.active !== true) {
    continue;
  }

  // Validar campos esenciales
  if (
    typeof profile.project_id !== "string" ||
    !/^[a-z0-9_-]+$/.test(profile.project_id) ||
    typeof profile.name !== "string" ||
    !profile.name.trim() ||
    !Array.isArray(profile.aliases) ||
    !profile.aliases.every(a => typeof a === "string") ||
    profile.schema_version !== "1.0"
  ) {
    warnings.push("Perfil con estructura incorrecta");
    continue;
  }

  // Detectar identificadores duplicados
  if (usedIds.has(profile.project_id)) {
    throw new Error(
      "Proyecto duplicado: " + profile.project_id
    );
  }

  usedIds.add(profile.project_id);

  // Incorporar proyecto al catalogo
  projects.push({
    project_id: profile.project_id,
    name: profile.name,
    aliases: profile.aliases,
    profile: profile
  });
}


const aliasOwners = new Map();

function normalizeAlias(value) {
  return String(value)
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .toLowerCase()
    .replace(/\s+/g, " ")
    .trim();
}

for (const project of projects) {
  const aliases = new Set([
    project.project_id,
    project.name,
    ...project.aliases
  ].map(normalizeAlias).filter(Boolean));

  for (const alias of aliases) {
    if (aliasOwners.has(alias)) {
      throw new Error(
        `Alias duplicado "${alias}" entre ` +
        `"${aliasOwners.get(alias)}" y ` +
        `"${project.project_id}"`
      );
    }

    aliasOwners.set(alias, project.project_id);
  }
}


return [{
  json: {
    catalog_version: "1.0",
    generated_at: new Date().toISOString(),
    total_projects: projects.length,
    projects: projects,
    warnings: warnings
  }
}];

const catalog = $input.first().json;
const record = $('Conservar registro de entrada').first().json;

// Normalizar texto para facilitar comparaciones
function normalize(value) {
  return String(value ?? "")
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .toLowerCase()
    .replace(/\s+/g, " ")
    .trim();
}

// Escapar caracteres especiales de expresiones regulares
function escapeRegex(value) {
  return value.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
}

const instruction = normalize(record.instruction);

const candidates = catalog.projects.map(project => ({
  project_id: project.project_id,
  name: project.name,
  aliases: [...new Set([
    project.project_id,
    project.name,
    ...project.aliases
  ].map(normalize).filter(Boolean))]
}));

// Buscar una referencia explícita al comienzo
const separator = instruction.indexOf(":");

let matches = [];
let method = null;

if (separator > 0) {
  const prefix = instruction.slice(0, separator).trim();

  matches = candidates.filter(project =>
    project.aliases.includes(prefix)
  );

  if (matches.length > 0) {
    method = "explicit_prefix";
  }
}

// Si no existe una referencia explícita,
// buscar nombres y alias en toda la instrucción
if (matches.length === 0) {
  matches = candidates.filter(project =>
    project.aliases.some(alias => {
      const pattern = new RegExp(
        "(^|[^\\p{L}\\p{N}_])" +
        escapeRegex(alias) +
        "($|[^\\p{L}\\p{N}_])",
        "u"
      );

      return pattern.test(instruction);
    })
  );

  if (matches.length > 0) {
    method = "alias_match";
  }
}

// Determinar el resultado
let classificationStatus = "UNIDENTIFIED";

if (matches.length === 1) {
  classificationStatus = "IDENTIFIED";
} else if (matches.length > 1) {
  classificationStatus = "AMBIGUOUS";
}

return [{
  json: {
    ...record,
    project: matches.length === 1
      ? matches[0].project_id
      : null,
    classification: {
      status: classificationStatus,
      method: method,
      candidates: matches.map(project => ({
        project_id: project.project_id,
        name: project.name
      })),
      classified_at: new Date().toISOString()
    }
  }
}];

const record = $input.first().json;
const catalog = $('Construir catalogo').first().json;

const isAmbiguous =
  record.classification.status === "AMBIGUOUS";

// Mostrar candidatos o todos los proyectos activos
const options = isAmbiguous
  ? record.classification.candidates
  : catalog.projects.map(project => ({
      project_id: project.project_id,
      name: project.name
    }));

// Construir lista de opciones
const numberedOptions = options.map((project, index) => ({
  option: index + 1,
  project_id: project.project_id,
  name: project.name
}));

const list = numberedOptions.map(project =>
  `${project.option}. ${project.name}`
).join("\n");

let message;

if (options.length === 0) {
  message =
    "No hay proyectos disponibles.\n\n" +
    "Configura al menos un perfil editorial activo.";
} else {
  const introduction = isAmbiguous
    ? "He identificado varios proyectos posibles."
    : "No he podido identificar el proyecto.";

  message =
    "⚠️ SOCIAL HUB — Clasificacion pendiente\n\n" +
    introduction + "\n\n" +
    "¿A que proyecto pertenece este contenido?\n\n" +
    list + "\n\n" +
    "ID del contenido: " + record.content_id + "\n\n" +
    "Selecciona el proyecto correspondiente.";
}

return [{
  json: {
    ...record,
    status: "PENDING_CLASSIFICATION",
    clarification: {
      required: true,
      reason: record.classification.status,
      options: numberedOptions,
      message: message,
      requested_at: new Date().toISOString()
    }
  }
}];

const record = $input.first().json;
const catalog = $('Construir catalogo').first().json;

const project = catalog.projects.find(
  p => p.project_id === record.project
);

if (!project) {
  throw new Error(
    "No se encontro el perfil: " + record.project
  );
}

const enabledPlatforms = Object.entries(
  project.profile.platforms ?? {}
)
  .filter(([name, config]) => config.enabled === true)
  .map(([name, config]) => name);

return [{
  json: {
    ...record,
    status: "CLASSIFIED",
    editorial_profile: project.profile,
    target_platforms: enabledPlatforms,
    clarification: {
      required: false
    },
    updated_at: new Date().toISOString()
  }
}];

const record = $input.first().json;

if (
  typeof record.content_id !== "string" ||
  !/^[a-zA-Z0-9_-]+$/.test(record.content_id)
) {
  throw new Error("Identificador de contenido invalido");
}

return [{
  json: {
    ...record,
    updated_at: new Date().toISOString()
  }
}];

const record = $input.first().json;

if (
  typeof record.content_id !== "string" ||
  typeof record.instruction !== "string"
) {
  throw new Error("Registro de entrada invalido");
}

return [{ json: record }];

const record = $('Preparar registro actualizado').first().json;

return [{
  json: {
    content_id: record.content_id,
    chat_id: record.chat_id ?? null,
    project: record.project,
    status: record.status,
    classification: record.classification,
    clarification: record.clarification ?? null
  }
}];
